  const impressumFaq = [
    ["Miért nem szerepel még céges azonosító a tesztoldalon?", "A repositoryban az Everyday Homes Kft. megnevezés csak nem hitelesített kezdeti törzsadatként szerepel. Székhely, adószám és cégjegyzékszám nélkül nem adunk ki megtévesztő impresszumot."],
    ["Mi kell az impresszum élesítéséhez?", "Hiteles cégkivonat vagy ellenőrzött vállalati törzsadat, képviseleti és kapcsolati adatok, tárhelyszolgáltatói adatok, valamint jogi jóváhagyás."],
    ["Elég a márkanév az üzemeltető azonosításához?", "Nem. A márkanév mellett a szolgáltatást nyújtó jogi személyt is pontosan meg kell nevezni, hogy az ügyfél tudja, kivel kerül kapcsolatba."],
    ["Miért fontos a székhely?", "A jogi személy hivatalos elérhetőségének része, és segít azonosítani a céget a nyilvántartásban. Nem helyettesíthető egy általános értékesítési régióval."],
    ["Miért kell cégjegyzékszám?", "Egyértelműen összeköti a megnevezett céget a közhiteles nyilvántartással, különösen akkor, ha hasonló nevű vállalkozások működnek."],
    ["Miért kell adószám?", "A gazdasági szereplő azonosító adatainak része, amely szerződéses és számlázási helyzetben is lényeges. Csak ellenőrzött formában közölhető."],
    ["Milyen e-mail-cím kerülhet az impresszumba?", "Olyan hivatalos, működő cím, amelyet kijelölt munkatársak kezelnek, és amelyen a jogi vagy szolgáltatási megkeresés nyomon követhető."],
    ["Kötelező telefonszámot közölni?", "A pontos kötelező tartalom a szolgáltatás jellegétől és a hatályos szabályoktól függ. Csak ténylegesen működő, vállalt ügyintézési csatornát szabad feltüntetni."],
    ["Mi a tárhelyszolgáltató szerepe?", "Az oldal technikai kiszolgálását végzi. Megnevezése és elérhetősége az éles infrastruktúra véglegesítése után tölthető ki."],
    ["Miért nem vehető át másik Imperial-márka impresszuma?", "Mert a márkák jogi üzemeltetője, domainje, adatfolyamata és szolgáltatója eltérhet. A közös cégcsoport nem teszi automatikusan azonossá a jogi felelőst."],
    ["Ki felel a weboldal tartalmáért?", "A végleges impresszumban a szolgáltató és szükség szerint a szerkesztői felelősség is megjelenik. Belső, nem ellenőrzött személynevet nem teszünk közzé."],
    ["Hogyan jelezhető tartalmi hiba?", "Az éles impresszumban megadott kapcsolati ponton, a pontos oldal és hibás állítás megjelölésével. A tesztkörnyezet fejlesztési felület, nem ügyfélszolgálat."],
    ["Az impresszum ajánlatnak minősül?", "Nem. Azonosító és szolgáltatási tájékoztató. Egyedi ár-, határidő- vagy műszaki vállalás csak külön ajánlatban és szerződésben jöhet létre."],
    ["A weboldal ára szerződéses ár?", "Csak akkor, ha az adott tartalom ezt kifejezetten, aktuális és ellenőrzött feltételekkel rögzíti. A részletes ajánlati határokat a konkrét dokumentum tartalmazza."],
    ["Ki használhatja az oldalon szereplő képeket?", "A jogtulajdonos vagy engedélyezett felhasználó feltételei szerint. A nyilvános megtekintés nem jelent automatikus másolási, átdolgozási vagy kereskedelmi felhasználási engedélyt."],
    ["Mi a helyzet a logóval és márkanévvel?", "Védett megjelölés vagy szerzői jogi mű lehet. Más cég vagy kampány nem használhatja úgy, hogy hivatalos kapcsolat vagy jóváhagyás látszatát keltse."],
    ["Hivatkozhat más oldal az Everyday Homes tartalmára?", "Jogszabályi keretek között, a forrás egyértelmű megjelölésével lehetséges hivatkozás. Teljes oldalak vagy adatbázisok átvételéhez külön engedély szükséges lehet."],
    ["Miért szerepel dátum és verzió az impresszumon?", "Mert az üzemeltető, szolgáltató vagy kapcsolati adat változhat. A verzió megmutatja, mely időpontban milyen tájékoztatás volt érvényes."],
    ["Mi történik, ha változik az üzemeltető?", "Az impresszumot, adatkezelést, szerződéses dokumentumokat, számlázást és kapcsolódó rendszereket összehangoltan kell módosítani, az érintettek szükséges tájékoztatásával."],
    ["Miért nem elég egy közösségi oldal elérhetősége?", "A közösségi profil külső platform, nem feltétlenül alkalmas hivatalos jogi vagy adatvédelmi megkeresésre, és nem helyettesíti a szolgáltató azonosítását."],
    ["Hol lesznek a fogyasztói tájékoztatások?", "A végleges jogi felülvizsgálat dönti el, mely tájékoztatások szükségesek a tényleges szolgáltatási modellhez. Nem helyezünk ki általános webáruházi sablont építési szolgáltatásra."],
    ["Miért marad review-required állapotban az oldal?", "Mert hiányzik a közhitelesen ellenőrzött jogi törzsadat és az éles tárhelyszolgáltatói konfiguráció. Ez tudatos, megkerülhetetlen kiadási blokk."],
    ["A hiányzó adatok ellenére működhet a tartalmi előnézet?", "Igen, ha nem gyűjt adatot, nem tesz külső kötelezettségvállalást és egyértelműen tesztkörnyezetként jelölt. Éles ügyfélszerzésre azonban nem használható."],
    ["Ki oldhatja fel a jogi kaput?", "A hiteles törzsadat gazdája és a kijelölt jogi jóváhagyó. Fejlesztő vagy szöveggeneráló rendszer nem töltheti ki feltételezésből."],
    ["Mi a kész impresszum ismertetőjele?", "Minden kötelező azonosító ellenőrzött, az elérhetőségek működnek, a tárhelyadat valós, a verzió dátumozott, és a jogi ellenőrzés eredménye naplózott."]
  ];

